// Test vectors for the runner. The table itself is vectors.inc, generated by
// scripts/gen_vectors.py from the gpsd logs, with verdicts from
// tests/nmea_reference.py and values from pynmea2.
#pragma once

#include <cstdint>

namespace runner {

enum class Expect : std::uint8_t { kRejected, kOther, kGGA, kRMC, kGSA, kVTG };

// What each slot of Vector::value and Vector::number holds, per type:
//
//   GGA  value: latitude, longitude, altitude, HDOP   number: quality, satellites
//   RMC  value: latitude, longitude, speed, course    number: ddmmyy, status char
//   GSA  value: PDOP, HDOP, VDOP, -                   number: fix type, PRN count
//   VTG  value: true, magnetic course, knots, km/h    number: mode char, -
//
// A value is present when its bit is set in `mask`; a number is -1 when the
// field was blank.
struct Vector {
    const char* line;  // without CR/LF
    std::uint8_t expect;
    std::int32_t time_ms;  // GGA/RMC time of day, -1 when blank
    std::uint8_t mask;
    double value[4];
    std::int32_t number[2];
};

extern const Vector kVectors[];
extern const std::uint32_t kVectorCount;

}  // namespace runner
